import { useEffect, useState } from 'react';
import {
  JxToggle,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxBadge,
} from '@jinx-ui/react';

export interface AppearanceSettings {
  theme: 'light' | 'dark' | 'system';
  scale: number;
  dense: boolean;
  font: string;
}

interface AppearanceSettingsScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

const themeLabels: Record<AppearanceSettings['theme'], string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceSettingsScreen({ onChange }: AppearanceSettingsScreenProps) {
  const [theme, setTheme] = useState<AppearanceSettings['theme']>('system');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState('sans');

  useEffect(() => {
    onChange?.({ theme, scale, dense, font });
  }, [theme, scale, dense, font, onChange]);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r)',
        maxWidth: 480,
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}
      >
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '1.25rem',
            color: 'var(--jx-text)',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent">{themeLabels[theme]}</JxBadge>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <span style={{ fontSize: '0.875rem', color: 'var(--jx-text-2)' }}>Тема</span>
        <JxToggle
          items={[
            { value: 'light', label: 'Светлая' },
            { value: 'dark', label: 'Тёмная' },
            { value: 'system', label: 'Системная' },
          ]}
          value={theme}
          onValueChange={(value) => setTheme(value as AppearanceSettings['theme'])}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={scale}
        onValueChange={setScale}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={dense}
        onChange={(event) => setDense(event.target.checked)}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        options={[
          { value: 'sans', label: 'Inter Tight (по умолчанию)' },
          { value: 'display', label: 'Fraunces' },
          { value: 'mono', label: 'JetBrains Mono' },
        ]}
        value={font}
        onValueChange={setFont}
      />
    </div>
  );
}

